Not sure why the counter is needed...  I would have expected something like this:

``` C
int opt_cipher_silent(const char *name, EVP_CIPHER **cipherp)
{
    OSSL_LIB_CTX *libctx = app_get0_libctx();
    const char *propq = app_get0_propq();

    EVP_CIPHER_free(*cipherp);

    
    ERR_set_mark();
    if ((*cipherp = EVP_CIPHER_fetch(libctx, name, propq)) != NULL
        || ((libctx == NULL && propq == NULL)
            && (*cipherp = (EVP_CIPHER *)EVP_get_cipherbyname(name)) != NULL)) {
        ERR_pop_to_mark();
        return 1;
    }
    ERR_clear_last_mark();
    return 0;
}
```
